};

var key = msg.topic;

if (sensors[key] !== undefined) {
    var val = parseFloat(msg.payload);
    if (!isNaN(val)) {
        var now = Date.now();
        var cutoff = now - 1440 * 60 * 1000;

        if (!sensors[key].values) sensors[key].values = [];
        sensors[key].values.push({ t: now, v: val });
        sensors[key].values = sensors[key].values.filter(function (e) { return e.t >= cutoff; });

        var vals = sensors[key].values.map(function (e) { return e.v; });
        var mn = Math.min.apply(null, vals);
        var mx = Math.max.apply(null, vals);
        var av = vals.reduce(function (a, b) { return a + b; }, 0) / vals.length;

        sensors[key].cur = val.toFixed(0) + ' ppm';
        //sensors[key].min = mn.toFixed(0) + ' ppm';
        //sensors[key].max = mx.toFixed(0) + ' ppm';
        //sensors[key].avg = (Math.round(av * 100) / 100).toFixed(0) + ' ppm';

        //sensors[key].cur = val.toFixed(0) ;
        sensors[key].min = mn.toFixed(0) ;
        sensors[key].max = mx.toFixed(0) ;
        sensors[key].avg = (Math.round(av * 100) / 100).toFixed(0) ;
    }
}

flow.set('co2_table', sensors);
msg.payload = Object.values(sensors);
return msg;

