// InfluxDB HTTP API returns:
// {"results":[{"series":[{"columns":["time","first","last"],"values":[["...",firstVal,lastVal]]}]}]}

try {
    const series = msg.payload.results[0].series[0];
    const cols = series.columns;
    const vals = series.values[0];

    const firstIdx = cols.indexOf("first");
    const lastIdx = cols.indexOf("last");

    const firstValue = vals[firstIdx];
    const lastValue = vals[lastIdx];

    if (firstValue === null || lastValue === null) {
        node.warn('Null values in result');
        msg.payload = { usage_kWh: 0, error: 'Null data' };
        return msg;
    }

    const usage = lastValue - firstValue;

    msg.payload = { usage_kWh: usage, data_points: 2 };

    node.status({ fill: "green", shape: "dot", text: `${usage.toFixed(2)} kWh` });

} catch (e) {
    node.error("Parse error: " + e.message);
    msg.payload = { usage_kWh: 0, error: 'Parse error' };
}

return msg;

