const now = new Date();

// Helper to convert local date → UTC ISO
function toUTCISOString(date) {
    const utc = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
    return utc.toISOString();
}

const ONE_HOUR = 60 * 60 * 1000;
let localStart, localStop;

// --- Determine local start/stop ---
if (range === 'day') {
    localStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    localStop = new Date(now);
}
else if (range === 'week') {
    localStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
    localStop = new Date(now);
}
else if (range === 'month') {
    localStart = new Date(now.getFullYear(), now.getMonth(), 1);
    localStop = new Date(now);
}
else if (range === 'custom') {
    if (!start || !stop) {
        node.warn('Custom range missing, defaulting to today');
        localStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        localStop = new Date(now);
    } else {
        localStart = new Date(start);
        localStop = new Date(stop);
        localStop.setHours(23, 59, 59, 999);
    }
}

// --- Add ±1 hour buffer and convert to UTC ---
msg.start = toUTCISOString(new Date(localStart.getTime() - ONE_HOUR));
msg.stop = toUTCISOString(new Date(localStop.getTime() + ONE_HOUR));

// --- Show quick visual status ---
node.status({
    fill: "green",
    shape: "dot",
    text: `Range: ${range} | ${localStart.toLocaleString()}–${localStop.toLocaleString()}`
});

return msg;

