return msg;

let totalSec = Number(msg.payload) || 0;
let minutes = Math.floor(totalSec / 60);
let seconds = totalSec % 60;

msg.payload = minutes > 0
    ? `${minutes} min ${seconds.toString().padStart(2, '0')} sec`
    : (totalSec === 0 ? "--" : `${seconds} sec`);

return msg;

