const DEVICE = "LoRa_XIAO_CO2_1_D893A8D4DB1C";
// --------------------------------

// Only fires when countdown reaches 0 (natural finish or abort)
if (msg.payload !== 0) return null;

let aborted = flow.get(`frc_abort.${DEVICE}`) || false;
flow.set(`frc_abort.${DEVICE}`, false);  // clear flag

if (aborted) {
    node.status({ fill: "red", shape: "dot", text: "Aborted" });
    return null;  // block — do nothing on abort
}

node.status({ fill: "green", shape: "dot", text: "Completing FRC..." });
return msg;  // pass through to FRC completion logic

// ---- CHANGE DEVICE ID HERE ----
const DEVICE = "LoRa_XIAO_CO2_1_D893A8D4DB1C";
// --------------------------------

// Read values
let target  = flow.get(`frc_pending_ppm.${DEVICE}`) || 432;
let actual  = flow.get(`frc_current_co2.${DEVICE}`) || 0;
let offset  = actual - target;
let now     = new Date().toLocaleString("en-US");

// Read existing MQTT state to preserve interval_days
// (We'll receive this via the MQTT state subscriber — stored in flow context)
let existing = flow.get(`frc_state.${DEVICE}`) || {};
let intervalDays = existing.interval_days || 7;

// Build updated state object
let state = {
    device:           DEVICE,
    last_frc:         now,
    last_frc_actual:  actual,
    last_frc_target:  target,
    last_frc_offset:  offset,
    interval_days:    intervalDays
};

// ---- Output 1: MQTT state update (retained) ----
let mqttMsg = {
    topic:   `MushLoRa/NodeRed/frc/state/${DEVICE}`,
    payload: JSON.stringify(state),
    retain:  true,
    qos:     1
};

// ---- Output 2: FRC command to OMG gateway ----
let omgMsg = {
    topic:   "MushLoRa/OMG_LORA_MOAPA/commands/MQTTtoLORA",
    payload: JSON.stringify({
        message: JSON.stringify({ target: DEVICE, frc: target })
    })
};

// ---- Output 3: Dashboard immediate updates (prior reading, corrected to, offset) ----
// Bundle all three in one pass — downstream function will split
let dashMsg = {
    payload: {
        prior:  actual,
        target: target,
        offset: offset,
        now:    now
    }
};

return [ mqttMsg, omgMsg, dashMsg ];

let d = msg.payload;
return [
    { payload: d.prior  },
    { payload: d.target },
    { payload: d.offset }
];

// ---- CHANGE DEVICE ID HERE ----
const DEVICE = "LoRa_XIAO_CO2_1_D893A8D4DB1C";
// --------------------------------

// Parse payload (may arrive as object or JSON string)
let state = (typeof msg.payload === "string")
    ? JSON.parse(msg.payload)
    : msg.payload;

// Store in flow context so Complete FRC can read interval_days
flow.set(`frc_state.${DEVICE}`, state);

let prior       = state.last_frc_actual  ?? "—";
let offset      = state.last_frc_offset  ?? "—";
let timestamp   = state.last_frc         ?? "—";
let intervalDays = state.interval_days   ?? 14;

// ---- Calculate days until next recal ----
let daysUntilDue;
let led = "green";

if (timestamp && timestamp !== "—") {
    let lastDate = new Date(timestamp);
    if (!isNaN(lastDate.getTime())) {
        let diffDays = (Date.now() - lastDate.getTime()) / (1000 * 60 * 60 * 24);
        daysUntilDue = Math.round(intervalDays - diffDays);

        if (daysUntilDue <= 0 && daysUntilDue > -3) {
            led = "yellow";
        } else if (daysUntilDue <= -3) {
            led = "red";
        } else {
            led = "green";
        }
    }
}

if (daysUntilDue === undefined || isNaN(daysUntilDue)) {
    daysUntilDue = "—";
}

return [
