    'F.R. ezo F': { loc: 'Fruiting Rear - ezo2', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'F.R. scd2 F': { loc: 'Fruiting Rear - scd2', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Incub. ezo F': { loc: 'Incubation - ezo3', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Incub. scd3 F': { loc: 'Incubation - scd3', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Pre-Con_TempF': { loc: 'Pre-Con Govee', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Lab TempF': { loc: 'Lab Govee', values: [], cur: '--', min: '--', max: '--', avg: '--' }
};

var key = msg.topic;

if (sensors[key] !== undefined) {
    var val = parseFloat(msg.payload);
    if (!isNaN(val)) {
        var now = Date.now();
        var cutoff = now - 1440 * 60 * 1000;

        if (!sensors[key].values) sensors[key].values = [];
        sensors[key].values.push({ t: now, v: val });
        sensors[key].values = sensors[key].values.filter(function (e) { return e.t >= cutoff; });

        var vals = sensors[key].values.map(function (e) { return e.v; });
        var mn = Math.min.apply(null, vals);
        var mx = Math.max.apply(null, vals);
        var av = vals.reduce(function (a, b) { return a + b; }, 0) / vals.length;

        sensors[key].cur = val.toFixed(1) + ' °F';
        sensors[key].min = mn.toFixed(1) ;
        sensors[key].max = mx.toFixed(1) ;
        sensors[key].avg = (Math.round(av * 100) / 100).toFixed(1);
    }
}

flow.set('tempF_table', sensors);
msg.payload = Object.values(sensors);
return msg;

let value;
if (msg.source === 'override') {
    // Triggered by override button — use last saved humidity
    value = Number(flow.get('lastHumidity', 'file')) || 0;
} else {
    // Real sensor reading — save it and use it
    value = Number(msg.payload);
    flow.set('lastHumidity', value, 'file');
}

let lowThreshold = Number(flow.get('lowThreshold', 'file')) || 0;
let highThreshold = Number(flow.get('highThreshold', 'file')) || 100;
let overrideMode = Number(flow.get('overrideMode', 'file')) || 0;
let lastState = Number(flow.get('lastState', 'memory')) || 0;

node.status({
    fill: 'blue', shape: 'dot',
    text: `RH:${value} Lo:${lowThreshold} Hi:${highThreshold} Mode:${overrideMode} Last:${lastState}`
});

// Override OFF — immediate, no delay
if (overrideMode === 1) {
    if (lastState !== 0) {
        flow.set('lastState', 0, 'memory');
        return { payload: 0, override: true };
    }
    return null;
}

// Override ON — immediate, no delay
if (overrideMode === 2) {
    if (lastState !== 1) {
        flow.set('lastState', 1, 'memory');
        return { payload: 1, override: true };
    }
    return null;
}

// Auto mode — only fire on state change
if (lastState === 0 && value > highThreshold) {
    let puckOn = global.get('puckPlugOn') === 1;
    if (puckOn) {
        node.status({
            fill: 'orange', shape: 'ring',
            text: `Blocked: puck ON (RH:${value})`
        });
        return null;
    }
    flow.set('lastState', 1, 'memory');
    return { payload: 1, override: false };
}
if (lastState === 1 && value < lowThreshold) {
    flow.set('lastState', 0, 'memory');
    return { payload: 0, override: false };
}

return null;

// Override ON skips delay entirely
if (msg.override === true) {
    node.status({ fill: 'green', shape: 'dot', text: 'Override ON - no delay' });
    node.send([msg, { payload: 'OFF' }]);  // fan ON, LED off (no delay active)
    return null;
}

let delayMinutes = Number(flow.get('fanOnDelay', 'file')) || 0;
let delayMs = delayMinutes * 60 * 1000;

if (delayMs === 0) {
    node.status({ fill: 'green', shape: 'dot', text: 'No delay - ON' });
    node.send([msg, { payload: 'OFF' }]);  // fan ON, LED off (no delay active)
    return null;
}

// Delay is active — light up the LED
node.status({ fill: 'yellow', shape: 'dot', text: `Delay: ${delayMinutes}m pending...` });
node.send([null, { payload: 'ON' }]);  // hold fan, LED on

setTimeout(() => {
    node.status({ fill: 'green', shape: 'dot', text: 'Delay done - ON sent' });
    node.send([msg, { payload: 'OFF' }]);  // fan ON, LED off
}, delayMs);

return null;

let raw = msg.payload;
let on = (raw === 'ON' || raw === 1 || raw === '1' || raw === true);
global.set('puckPlugOn', on ? 1 : 0, 'memory');
node.status({ fill: on ? 'green' : 'grey', shape: 'dot', text: on ? 'Puck ON' : 'Puck OFF' });
return null;

var hum = Number(msg.payload);
var highSet = Number(flow.get('hum_highThreshold')) || 90;
var lowSet  = Number(flow.get('hum_lowThreshold'))  || 70;
var override = Number(flow.get('hum_overrideMode')) || 0;

// Alert thresholds are ±5% beyond setpoints
var alertHigh = highSet + 5;
var alertLow  = lowSet  - 5;

// If override is active (1=OFF forced, 2=ON forced),
// suppress alerts — operator is intentionally in control
if (override !== 0) {
    node.status({ fill:'yellow', shape:'dot',
        text:'Override active (' + override + ') — alerts suppressed' });
    return null;
}

node.status({ fill:'blue', shape:'dot',
