msg.hum       = hum;
msg.alertHigh = alertHigh;
msg.alertLow  = alertLow;
msg.highSet   = highSet;
msg.lowSet    = lowSet;

// Output 1: check high | Output 2: check low
return [msg, msg];

var hum = msg.hum;
