if (flow.get('scd1_alert_enabled', 'file')) msgs[1] = { topic: 'control', payload: 'close' };
return msgs;

flow.set('snooze_active', false);
flow.set('snooze_until', 0);
node.warn('Snooze cancelled');

// Reopen only gates that have their switch ON
var msgs = [null, null];
if (flow.get('hum_alert_enabled', 'file'))  msgs[0] = { topic: 'control', payload: 'open' };
if (flow.get('scd1_alert_enabled', 'file')) msgs[1] = { topic: 'control', payload: 'open' };
