};
return msg;

var lines = msg.payload.trim().split('\n');
var raw = {};
lines.forEach(function (line) {
    var idx = line.indexOf(':');
    if (idx === -1) return;
    raw[line.substring(0, idx)] = line.substring(idx + 1).trim();
});

var tempMatch = (raw.TEMP || '').match(/([\d.]+)/);
msg.tempC = tempMatch ? parseFloat(tempMatch[1]) : null;

var loadParts = (raw.LOAD || '').split(' ');
var load1 = parseFloat(loadParts[0]) || 0;
var cores = parseInt(raw.CORES) || 1;
msg.loadPct = Math.round((load1 / cores) * 1000) / 10;

var memTotal = parseFloat(raw.MEM_TOTAL) || 0;
var memUsed = parseFloat(raw.MEM_USED) || 0;
var memFree = parseFloat(raw.MEM_FREE) || 0;
var memShared = parseFloat(raw.MEM_SHARED) || 0;
var memBuffCache = parseFloat(raw.MEM_BUFFCACHE) || 0;
var memAvailable = parseFloat(raw.MEM_AVAIL) || 0;
var swapTotal = parseFloat(raw.SWAP_TOTAL) || 0;
var swapUsed = parseFloat(raw.SWAP_USED) || 0;
var swapFree = parseFloat(raw.SWAP_FREE) || 0;

msg.memAvailableMiB = memAvailable;
msg.memAvailablePct = memTotal ? Math.round((memAvailable / memTotal) * 1000) / 10 : 0;
msg.swapUsedMiB = swapUsed;

msg.diskPct = parseInt(raw.DISK) || 0;

var totalSeconds = parseFloat((raw.UPTIME || '0').split(' ')[0]);
var days = Math.floor(totalSeconds / 86400);
var hours = Math.floor((totalSeconds % 86400) / 3600);
var minutes = Math.floor((totalSeconds % 3600) / 60);
msg.uptime = days + "d " + hours + "h " + minutes + "m";

msg.hostname = raw.HOST || 'unknown';
msg.ip = (raw.IP || '').trim();
msg.topic = "status/" + msg.hostname + "/ip";

msg.lastUpdated = new Date().toLocaleTimeString('en-US');

msg.payload = [
    { Type: "Memory", Total: memTotal, Used: memUsed, Free: memFree, Shared: memShared, "Buff/Cache": memBuffCache, Available: memAvailable },
    { Type: "Swap", Total: swapTotal, Used: swapUsed, Free: swapFree }
];

return msg;

