// Retrieve existing saved times (persistent)
var saved = flow.get("timer1_times", "file") || { on: "00:00:00", off: "00:00:00" };

// Merge incoming msg values
if (msg.topic === "on_time1" && msg.payload) saved.on = msg.payload;
if (msg.topic === "off_time1" && msg.payload) saved.off = msg.payload;

// Validate times
function checktime(time) {
    if (!time) return false;
    const parts = time.split(":");
    if (parts.length < 2) return false;
    if (parseInt(parts[0]) > 23 || parseInt(parts[1]) > 59) return false;
    if (parts[2] !== undefined && parseInt(parts[2]) > 59) return false;
    return true;
}
if (!checktime(saved.on) || !checktime(saved.off)) {
    node.warn("Invalid times, reverting to previous or default");
    saved.on = saved.on || "00:00:00";
    saved.off = saved.off || "00:00:00";
}

// Persist both times
flow.set("timer1_times", saved, "file");

// Also keep a temporary buffer for UI display (optional)
flow.set("timer1_input_buffer", { on: saved.on, off: saved.off });

// Build message for EZTimer & dashboard
msg.payload = { ontime: saved.on, offtime: saved.off };
return msg;

